<div class="d-flex flex-wrap justify-content-between gap-3 align-items-center mb-4"><div><h1 class="h3"><?= $manage ? 'Administrar cursos' : 'Academia INMOVA' ?></h1><p class="text-muted mb-0"><?= $manage ? 'Crea contenido y publica cursos para el equipo.' : 'Aprende a tu ritmo y consulta tu progreso.' ?></p></div><div class="d-flex flex-wrap gap-2"><?php if ($manage): ?><a class="btn btn-primary" href="<?= BASE_URL ?>/academy/course/edit">Nuevo curso</a><a class="btn btn-outline-secondary" href="<?= BASE_URL ?>/academy">Ver catálogo</a><?php elseif (in_array($user['rol'],['superadmin','admin','instructor'],true)): ?><a class="btn btn-outline-primary" href="<?= BASE_URL ?>/academy/manage">Administrar cursos</a><?php endif; ?></div></div>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= e($success) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php if (Simulation::allowed($user)): ?><a class="btn btn-outline-primary mb-4" href="<?= BASE_URL ?>/simulations">Practicar en el simulador de ventas</a><?php endif; ?>
<?php if (!$manage): ?><div class="d-flex gap-2 mb-4"><a class="btn <?= !$mine ? 'btn-primary' : 'btn-outline-primary' ?>" href="<?= BASE_URL ?>/academy">Todos los cursos</a><a class="btn <?= $mine ? 'btn-primary' : 'btn-outline-primary' ?>" href="<?= BASE_URL ?>/academy?mine=1">Mis cursos</a></div><?php endif; ?>
<?php if (!$courses): ?><div class="card card-body text-center py-5"><h2 class="h5"><?= $manage ? 'Aún no tienes cursos para administrar' : ($mine ? 'No tienes inscripciones en cursos publicados' : 'Próximamente encontrarás cursos aquí') ?></h2><p class="text-muted mb-0"><?= $manage ? 'Crea un curso como borrador, agrega lecciones y luego publícalo.' : 'Los cursos activos y publicados aparecerán en este catálogo.' ?></p></div><?php endif; ?>
<div class="row g-4"><?php foreach ($courses as $item): ?><article class="col-md-6 col-lg-4"><div class="card card-body h-100 shadow-sm"><p class="text-uppercase small text-muted">Academia · <?= (int)$item['lecciones'] ?> lección(es)</p><h2 class="h5"><?= e($item['titulo']) ?></h2><p class="small text-muted">Instructor: <?= e($item['instructor']) ?></p><p style="white-space:pre-wrap"><?= e(mb_strimwidth($item['descripcion'] ?? '',0,220,'…','UTF-8')) ?></p><div class="mb-3"><?php if ($manage): ?><span class="badge <?= !$item['estado'] ? 'text-bg-secondary' : ($item['publicado'] ? 'text-bg-success' : 'text-bg-warning') ?>"><?= !$item['estado'] ? 'Archivado' : ($item['publicado'] ? 'Publicado' : 'Borrador') ?></span><?php elseif ($item['inscripcion']): ?><span class="badge text-bg-info"><?= $item['inscripcion']==='completada' ? 'Lecciones completadas' : 'Inscrito' ?></span><?php endif; ?></div><a class="btn btn-outline-primary mt-auto" href="<?= BASE_URL ?><?= $manage ? '/academy/course/edit' : '/academy/course' ?>?id=<?= (int)$item['id'] ?>"><?= $manage ? 'Gestionar curso' : 'Ver curso' ?></a></div></article><?php endforeach; ?></div>
<p class="small text-muted mt-3">Se muestran hasta 100 cursos. Completar las lecciones registra tu avance; aprueba el examen final de los cursos que lo incluyan para obtener tu certificado.</p>

